        var it = { key: 'pr-' + n, labels: ['agent:review'], issueNumber: null,
                   prNumber: n, draft: false, branch: BRANCH, headRepo: FORK };
        if (extra) { for (var k in extra) { if (extra.hasOwnProperty(k)) it[k] = extra[k]; } }
        return it;
