var DEFAULT_LEG_WORKFLOW = 'ai-teammate.yml';

// Active-state vocabulary — one list, the validationLiveness shape the rest
// of the engine already uses.
var ACTIVE_RUN_STATES = ['queued', 'in_progress', 'waiting', 'pending'];

