    ACTIVE_RUN_STATES: ACTIVE_RUN_STATES,
    DEFAULT_STALE_NON_RUNNING_MS: DEFAULT_STALE_NON_RUNNING_MS,
    isLegRun: isLegRun,
    isActiveStatus: isActiveStatus,
    isStaleNonRunning: isStaleNonRunning,
    matchesBranch: matchesBranch,
