        var runs = [forkLegRun({ path: OTHER_PATH })];
        assert.notOk(guard.hasActiveLegRunForPull(runs, PR, { nowMs: NOW_MS }),
            'validation CI on main stays inert for the leg guard (isLegRun parity)');
