            var mInput = /^\s+inputs:\s*$/.exec(line);
            if (!inInputs) {
                if (mInput) { inInputs = true; baseIndent = mInput[0].length - 'inputs:'.length - 1; }
                continue;
            }
            // inside inputs: entry keys are indented deeper than 'inputs:'
            var mKey = /^\s+([A-Za-z0-9_]+):\s*$/.exec(line);
