// ─── gh-1028: duplicate CONCURRENT rework legs on one PR (live 2026-10-18
// 08:04–08:09Z: PR #1017 / gh-1000 / branch ai/gh-1000 got TWO concurrent
// rework legs for ONE rework cycle — run 39110030366 PR-armed at 08:04:12Z
// titled 'workflow_dispatch # rework' + run 39110364398 issue-armed at
// 08:09:31Z titled 'workflow_dispatch #1000 rework'). The first leg pushed,
// the head moved (c2e0d28f → 94988905), so the gh-806 (pr, head) latch keyed
// a NEW head and never suppressed the second arm; and the PR-armed factory
// run title carries NO '· gh-N'/'#N' anchor token, so the title guards
// (gh-715/gh-944) were blind to it too. The branch-keyed probe (an ACTIVE
// ai-teammate run whose head_branch IS the dispatch branch, regardless of
// head sha) closes both holes for BOTH dispatch arms — the branch is the
// leg's single writer and two concurrent legs race every push.
suite('smAgent: branch-keyed leg dedupe (gh-1028)', function () {
    var BRANCH = 'ai/gh-100';
    var HEAD_OLD = 'c2e0d28f00000000000000000000000000000000';
    var HEAD_NEW = '94988905000000000000000000000000000000000';
    var LEG_PATH = '.github/workflows/ai-teammate.yml';

    // The first leg's in-flight run — dispatched on the OLD head, no anchor
    // token in the title (the exact PR-armed factory shape from the ticket).
    function legRun(head) {
        return { id: 39110030366, status: 'in_progress',
                 display_title: 'workflow_dispatch # rework',
                 path: LEG_PATH, head_branch: BRANCH, head_sha: head || HEAD_OLD };
    }

    function reworkSource(prLabels) {
        return function (rule, ctx) {
            var q = (rule && rule.query) || {};
            if (q.type === 'issue') {
                return [{ key: 'gh-100', labels: ['agent:rework'], issueNumber: 100,
                          prNumber: 1017, branch: BRANCH, author: 'ai-teammate',
                          headSha: HEAD_NEW, pr: { labels: prLabels } }];
            }
            return [{ key: 'pr-1017', labels: prLabels, issueNumber: 100,
                      prNumber: 1017, branch: BRANCH, author: 'ai-teammate',
                      headSha: HEAD_NEW }];
        };
    }

    var FILEMAP = { '../.dmtools/config.js': 'module.exports = { repository: { owner: "epam", repo: "dmtools-dart" } };' };

    // Local copies of the gh-715 suite helpers (they are suite-scoped there).
    function deployedRules(ids) {
        var cfg = JSON.parse(file_read({ path: 'sm_github.json' }));
        var rules = (cfg.params && cfg.params.jobParams && cfg.params.jobParams.rules) || [];
        var byId = {};
        rules.forEach(function (r) { byId[r.id] = r; });
        return ids.map(function (id) {
            assert.ok(byId[id], 'deployed rule ' + id + ' exists');
            return byId[id];
        });
    }

    function ghParams(rules) {
        return { jobParams: { owner: 'epam', repo: 'dmtools-dart',
                              machineAuthor: 'ai-teammate', rules: rules } };
    }

    test('AC2: a head move between dispatches does NOT bypass the probe — the active run on the OLD head still suppresses', function () {
        var sm = makeSmAgent({
            fileMap: FILEMAP,
            github: { items: reworkSource([]),
                      issue: { number: 100, state: 'open', labels: [{ name: 'agent:rework' }] } },
            workflowRuns: { in_progress: [legRun(HEAD_OLD)] } // first leg on the MOVED-FROM head
        });

        sm.action(ghParams(deployedRules(['rework-on-red-ci'])));

        assert.equal(sm.capturedTriggers.length, 0,
            'the issue-armed dispatch sees the PR-armed leg in flight on the SAME branch even though the head moved');
    });

    test('AC1: issue-armed and PR-armed rework for the SAME PR in one tick dispatch EXACTLY ONE leg', function () {
        // The first dispatch materializes its run (the live 08:04 leg); the
        // second arm's probe must then see it. The run's head is the OLD
        // head — the leg pushed mid-flight is exactly what moved the head
        // before the second arm fired.
        var opts = {
            fileMap: FILEMAP,
            github: { items: reworkSource(['agent:rework']),
                      issue: { number: 100, state: 'open', labels: [{ name: 'agent:rework' }] } },
            workflowRuns: { in_progress: [] },
            onTrigger: function () { opts.workflowRuns.in_progress.push(legRun(HEAD_OLD)); }
        };
        var sm = makeSmAgent(opts);

        sm.action(ghParams(deployedRules(['rework-on-red-ci', 'rework-on-label'])));

        assert.equal(sm.capturedTriggers.length, 1,
            'one leg wins — the second arm lands on the branch the first leg already owns');
    });

    test('a COMPLETED leg run on the branch does not suppress — the next arm dispatches (dead-letter re-fire intact)', function () {
        var sm = makeSmAgent({
            fileMap: FILEMAP,
            github: { items: reworkSource([]),
                      issue: { number: 100, state: 'open', labels: [{ name: 'agent:rework' }] } },
            workflowRuns: { in_progress: [
                Object.assign(legRun(HEAD_OLD), { status: 'completed', conclusion: 'success',
                    updated_at: '2026-10-18T08:05:00.000Z' })
            ] }
        });

        sm.action(ghParams(deployedRules(['rework-on-red-ci'])));

        assert.equal(sm.capturedTriggers.length, 1,
            'the concluded leg owns nothing — a consumed-without-work arm re-fires as designed');
    });

    test('an active leg run on a DIFFERENT branch does not suppress', function () {
        var other = legRun(HEAD_OLD);
        other.head_branch = 'ai/gh-999';
        var sm = makeSmAgent({
            fileMap: FILEMAP,
            github: { items: reworkSource([]),
                      issue: { number: 100, state: 'open', labels: [{ name: 'agent:rework' }] } },
            workflowRuns: { in_progress: [other] }
        });

        sm.action(ghParams(deployedRules(['rework-on-red-ci'])));

        assert.equal(sm.capturedTriggers.length, 1, 'another branch is another writer — dispatch proceeds');
    });

    test('branch-guard suppression does NOT consume the PR arm — rework-on-label keeps its label for the next tick', function () {
        var sm = makeSmAgent({
            fileMap: FILEMAP,
            github: { items: [{ key: 'pr-1017', labels: ['agent:rework'], issueNumber: 100,
                                prNumber: 1017, branch: BRANCH, author: 'ai-teammate',
                                headSha: HEAD_NEW }] },
            workflowRuns: { in_progress: [legRun(HEAD_OLD)] }
        });

        sm.action(ghParams(deployedRules(['rework-on-label'])));

        assert.equal(sm.capturedTriggers.length, 0, 'suppressed — a leg already owns the branch');
        assert.equal(sm.capturedPrLabelRemoves.length, 0,
            'the arm survives the suppression (unlike the gh-715 cross-anchor consume) — if the in-flight leg dies silently, the arm re-fires next tick');
    });

    test('a dispatch that does NOT land on the branch (ref=main) is outside the guard', function () {
        var rules = deployedRules(['rework-on-label']).map(function (r) {
            var r2 = Object.assign({}, r); r2.workflowRef = 'main'; return r2;
        });
        var sm = makeSmAgent({
            fileMap: FILEMAP,
            github: { items: [{ key: 'pr-1017', labels: ['agent:rework'], issueNumber: 100,
                                prNumber: 1017, branch: BRANCH, author: 'ai-teammate',
                                headSha: HEAD_NEW }] },
            workflowRuns: { in_progress: [legRun(HEAD_OLD)] }
        });

        sm.action(ghParams(rules));

        assert.equal(sm.capturedTriggers.length, 1, 'a main-ref leg is not the branch writer — no race to guard');
    });
});

// ─── gh-682: standing cancelled-checks remedy. Live evidence: fa#1202
// (head 898efd4) — all 4 kicker push-runs on ai/gh-1171 CANCELLED
// 21:43–23:05 as refresh pushes landed, required checks ended CANCELLED →
// PR BLOCKED until a manual rerun (23:26); fa#1203 twice more (23:47,
// 23:57); still reproducing 2026-10-04 06:21–06:22 — eight branche…

/**
 * branchLegGuard.js — gh-1028 branch-keyed in-flight leg probe (pure side).
 *
 * Live evidence (dmtools-agents PR #1017 / gh-1000, 2026-10-18 08:04–08:09Z):
 * ONE rework cycle got TWO concurrent rework legs —
 *   run 39110030366 (08:04:12Z, PR-armed from rework-on-label) — its factory
 *     run title 'workflow_dispatch # rework' carries NO anchor token, so
 *     the title guards (gh-715 cross-anchor, gh-944 '#<n>' tokens) were
 *     blind to it from the issue-armed path;
 *   run 39110364398 (08:09:31Z, issue-armed from rework-on-red-ci) — between
 *     the dispatches the first leg pushed and the head moved
 *     (c2e0d28f → 94988905), so the gh-806 (pr, head) latch keyed a NEW
 *     head and never suppressed the second arm.
 * Both legs checkout/rewrite the same branch concurrently → token waste ×2
 * and a push race (the second pusher lands on a moved checkout).
 *
 * This module is the missing probe: the leg workflow dispatched with
 * workflowRef={branch} lands ON the PR branch and is the branch's SINGLE
 * WRITER — so an ACTIVE run of the leg workflow whose head_branch IS the
 * dispatch branch, REGARDLESS of head_sha, means the branch is owned and
 * no second leg may be dispatched onto it. Both rework dispatch arms
 * (issue-anchored rework-on-red-ci and PR-anchored rework-on-label) flow
 * through smAgent.triggerWorkflow, so one gate there covers both paths —
 * AC1 (one leg per PR per rework cycle) and AC2 (a head move between
 * dispatches does not bypass the probe) by construction.
 *
 * Pure functions, no tool globals — smAgent wires the transport (the
 * scm.listWorkflowRuns per-status fan-out), tests inject nothing.
 * GraalJS-clean: var + plain functions, JSON-safe data only.
 */

'use strict';

// The rework/review/dev leg workflow — the same default the dispatch side
// (smAgent triggerWorkflow) and the gh-806 latch use.
var DEFAULT_LEG_WORKFLOW = 'ai-teammate.yml';

// Active-state vocabulary — one list, the validationLiveness shape the rest
// of the engine already uses.
var ACTIVE_RUN_STATES = ['queued', 'in_progress', 'waiting', 'pending'];

// gh-806-adjacent stale bound for NON-running active states: a run stuck
// 'queued' (never materialized, superseded in the concurrency group, dead
// runner) for longer than this owns nothing — the dead dispatch self-heals
// and the next arm may fire. Mirrors smAgent's
// STALE_NON_RUNNING_WORKFLOW_MS (6h). in_progress runs NEVER age out here:
// a live leg owns the branch past any window.
var DEFAULT_STALE_NON_RUNNING_MS = 6 * 60 * 60 * 1000;

function workflowFileOf(opts) {
    var wf = opts && opts.workflowFile;
    return (wf && typeof wf === 'string') ? wf : DEFAULT_LEG_WORKFLOW;
}

/**
 * True when the run belongs to the leg workflow (path ends with
 * '/<workflowFile>') — reworkLatch.isLegRun parity: validation CI or
 * kicker runs on the same branch must never influence the guard.
 */
function isLegRun(run, workflowFile) {
    if (!run) return false;
    var suffix = '/' + String(workflowFile || DEFAULT_LEG_WORKFLOW);
    var path = String(run.path || '');
    return path.length >= suffix.length &&
        path.slice(path.length - suffix.length) === suffix;
}

function isActiveStatus(status) {
    return ACTIVE_RUN_STATES.indexOf(status) !== -1;
}

function runTimestampMs(run) {
    var value = run && (run.updated_at || run.created_at);
    if (!value) return null;
    var ms = Date.parse(String(value));
    return isNaN(ms) ? null : ms;
}

/**
 * Non-in_progress active state aged past the stale bound — a queued/waiting/
 * pending run whose last timestamp is older than staleNonRunningMs. An
 * in_progress run is never stale here (the caller gates on that).
 */
function isStaleNonRunning(run, nowMs, staleMs) {
    if (run && run.status === 'in_progress') return false;
    var ts = runTimestampMs(run);
    if (ts === null || nowMs === null) return false;
    return (nowMs - ts) > staleMs;
}

/**
 * Exact branch match, type-tolerant (REST payloads carry strings, some
 * bridges coerce). A run without head_branch never matches — the title-
 * only run payloads the budget probes consume stay inert.
 */
function matchesBranch(run, branch) {
    if (!run || run.head_branch === undefined || run.head_branch === null) return false;
    return String(run.head_branch) === String(branch);
}

/**
 * THE GATE (gh-1028): is a leg in flight on `branch`? True iff some run is
 *   - an ACTIVE status (queued/in_progress/waiting/pending), not a stale
 *     non-running zombie (aged out past staleNonRunningMs; in_progress
 *     never ages out);
 *   - a run of the leg workflow (path suffix);
 *   - on EXACTLY this branch (head_branch equality) — REGARDLESS of
 *     head_sha, so a head move between dispatches cannot bypass it (AC2).
 *
 * opts: workflowFile (default ai-teammate.yml), staleNonRunningMs
 * (default 6h), nowMs (default Date.now()). A caller without a clock
 * degrades to fail-closed: without nowMs no run can be proven stale, so
 * every active run counts — one deferred dispatch beats a stacked leg.
 */
function staleMsOf(opts) {
    return (opts && typeof opts.staleNonRunningMs === 'number' && opts.staleNonRunningMs > 0)
        ? opts.staleNonRunningMs : DEFAULT_STALE_NON_RUNNING_MS;
}

function nowMsOf(opts) {
    return (opts && typeof opts.nowMs === 'number' && !isNaN(opts.nowMs))
        ? opts.nowMs : null;
}

/** One run owns the branch: active, non-stale, the leg workflow, on-branch. */
function legRunOwnsBranch(run, branch, workflowFile, nowMs, staleMs) {
    if (!run || !isActiveStatus(run.status)) return false;
    if (run.status !== 'in_progress' && nowMs !== null &&
        isStaleNonRunning(run, nowMs, staleMs)) return false;
    return isLegRun(run, workflowFile) && matchesBranch(run, branch);
}

function hasActiveLegRunOnBranch(runs, branch, opts) {
    if (!branch || typeof branch !== 'string' || !Array.isArray(runs)) return false;
    var workflowFile = workflowFileOf(opts);
    var staleMs = staleMsOf(opts);
    var nowMs = nowMsOf(opts);
    for (var i = 0; i < runs.length; i++) {
        if (legRunOwnsBranch(runs[i], branch, workflowFile, nowMs, staleMs)) return true;
    }
    return false;
}

