    var PR = 1591;

    function forkLegRun(opts) {
        opts = opts || {};
        var r = run('in_progress', { branch: 'main' });
        r.display_title = opts.title !== undefined ? opts.title : '▶ rework (SM) · pr-1591';
        if (opts.pullBranch) r.head_branch = 'refs/pull/1591/head';
