// and the next arm may fire. Mirrors smAgent's
// STALE_NON_RUNNING_WORKFLOW_MS (6h). in_progress runs NEVER age out here:
// a live leg owns the branch past any window.
var DEFAULT_STALE_NON_RUNNING_MS = 6 * 60 * 60 * 1000;

