        if (idx === -1) break;
        var next = s.charAt(idx + token.length);
        var prev = idx > 0 ? s.charAt(idx - 1) : '';
        var nextOk = !((next >= '0' && next <= '9') || next === '-');
        var prevOk = !((prev >= 'a' && prev <= 'z') || (prev >= 'A' && prev <= 'Z') ||
